def _propagate(source):
    # Collect every compute cell that (transitively) depends on the source.
    affected = set()
    stack = list(source._observers)
    while stack:
        cell = stack.pop()
        if cell in affected:
            continue
        affected.add(cell)
        stack.extend(cell._observers)

    # Topologically order the affected cells so that each cell is recomputed
    # only after all of its affected inputs have been.
    order = []
    remaining = set(affected)
    while remaining:
        for cell in list(remaining):
            if all(inp not in remaining for inp in cell._inputs):
                order.append(cell)
                remaining.remove(cell)

    for cell in order:
        cell._recompute()

